package com.athleet.core.storage;

import java.io.InputStream;
import java.net.URI;
import java.time.Duration;
import java.util.Optional;

/**
 * Where uploaded bytes live. Keys are always generated by the server; callers never pass a client file name.
 * Implementations: local folder (development), S3-compatible bucket in an Indian region (later).
 */
public interface FileStorage {

    void put(String key, byte[] bytes);

    InputStream open(String key);

    void delete(String key);

    /** A direct pre-signed URL when the backend supports one (S3); empty for local storage, which streams through the API. */
    default Optional<URI> presignedGet(String key, Duration ttl) {
        return Optional.empty();
    }
}
